# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"
require "securerandom"

RSpec.describe Timekeeping::LocalEntry do
  # "`locked` is true when any reservation row, provisional or committed, exists for the entry in the same company."
  it "local entry with_reserved reads reservations of the same company and ignores entries.locked" do
    company_id = 7001
    build = lambda do |locked|
      described_class.create!(company_id:, user_id: 1, project_id: 1, work_date: Date.new(2026, 3, 2),
                              duration: 1.5, bill_status: "unbilled", locked:)
    end
    provisional = build.call(false)
    committed = build.call(false)
    unreserved = build.call(true)
    [[provisional, "provisional"], [committed, "committed"]].each do |entry, state|
      ActiveRecord::Base.connection.execute(ActiveRecord::Base.sanitize_sql_array([
        "INSERT INTO reservations (company_id, entry_id, invoice_id, operation_id, state, disposition, created_at) " \
        "VALUES (?, ?, 1, ?, ?, 'active', NOW())", company_id, entry.id, SecureRandom.uuid, state
      ]))
    end

    reserved = described_class.with_reserved.where(company_id:).to_h { |row| [row.id, row.reserved] }

    expect(reserved).to eq(provisional.id => true, committed.id => true, unreserved.id => false)
  end
end
